def is_pattern_match(s: str, p: str) -> bool:
    """Check if string s matches the pattern p, where:
    - '*' in p matches any sequence of characters (including empty)
    - '?' in p matches any single character
    """
    def match(i: int, j: int) -> bool:
        if i == len(s):
            return j == len(p) or (j < len(p) and p[j] == '*')
        if j == len(p):
            return i == len(s)

        if p[j] == '?':
            return match(i + 1, j + 1)
        if p[j] == '*':
            return match(i, j + 1) or match(i + 1, j)

        return s[i] == p[j] and match(i + 1, j + 1)

    return match(0, 0)

