def decode_message(encoded_str):
    result = ''
    for char in encoded_str:
        if 'A' <= char <= 'Z':
            result += chr(ord('A') + (ord(char) - ord('A') - 3) % 26)
        elif 'a' <= char <= 'z':
            result += chr(ord('a') + (ord(char) - ord('a') - 3) % 26)
        else:
            result += char
    return result

def find_min_abs_difference(arr):
    if len(arr) < 2:
        return 0
    min_diff = float('inf')
    for i in range(1, len(arr)):
        diff = abs(arr[i] - arr[i - 1])
        if diff < min_diff:
            min_diff = diff
    return min_diff

def find_duplicate_subarrays(arr):
    seen = {}
    n = len(arr)
    for i in range(n):
        subarr = []
        for j in range(i, n):
            subarr.append(arr[j])
            key = tuple(subarr)
            if key in seen:
                seen[key] += 1
            else:
                seen[key] = 1
    max_len = 0
    for key, count in seen.items():
        if count >= 2:
            max_len = max(max_len, len(key))
    return max_len if max_len > 0 else 1

