def merge_dicts_with_priority(d1: dict, d2: dict, priority: str) -> dict:
    """
    Merge two dictionaries. If there are overlapping keys, the values from the
    dictionary specified by 'priority' are used. The 'priority' parameter can be
    'd1' or 'd2'.
    """
    result = {}
    if priority == 'd1':
        for key, value in d1.items():
            result[key] = value
        for key, value in d2.items():
            if key not in result:
                result[key] = value
    elif priority == 'd2':
        for key, value in d2.items():
            result[key] = value
        for key, value in d1.items():
            if key not in result:
                result[key] = value
    return result

def find_longest_common_subsequence(strings):
    if not strings:
        return 0

    # Start with the first string as the initial candidate
    lcs = list(strings[0])
    for s in strings[1:]:
        new_lcs = []
        i = j = 0
        while i < len(lcs) and j < len(s):
            if lcs[i] == s[j]:
                new_lcs.append(lcs[i])
                i += 1
                j += 1
            elif lcs[i] < s[j]:
                i += 1
            else:
                j += 1
        lcs = new_lcs

    return len(lcs)

def count_pattern_occurrences(text, pattern):
    import re
    matches = re.finditer(pattern, text)
    return sum(1 for _ in matches)

def count_even_digits(arr):
    count = 0
    for num in arr:
        digits = len(str(abs(num)))
        if digits % 2 == 0:
            count += 1
    return count

def valid_braces(lst):
    left = lst[0]
    right = lst[1]
    if left == right:
        return 'No'
    return 'Yes' if (left.count('{') == right.count('}') and left.count('}') == right.count('{')) else 'No'

def maxPath(grid, k):
    from heapq import heappush, heappop
    import copy

    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Priority queue: (current value, current path, current position (row, col))
    heap = []

    # Find the maximum starting value
    max_val = -1
    for i in range(n):
        for j in range(n):
            if grid[i][j] > max_val:
                max_val = grid[i][j]

    # Start with the maximum value
    for i in range(n):
        for j in range(n):
            if grid[i][j] == max_val:
                path = [grid[i][j]]
                heappush(heap, (-grid[i][j], path, (i, j)))

    while heap:
        current_val, path, (row, col) = heappop(heap)
        current_val = -current_val

        if len(path) == k:
            return path

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < n and 0 <= new_col < n:
                new_path = path + [grid[new_row][new_col]]
                heappush(heap, (-grid[new_row][new_col], new_path, (new_row, new_col)))

    return []

def tetra(n):
    if n < 0:
        return []
    result = [0, 1, 1, 2]
    for i in range(4, n + 1):
        result.append(result[i-1] + result[i-2] + result[i-3] + result[i-4])
    return result[:n+1] if n >= 0 else []

def is_last_char_alone(txt):
    if not txt:
        return False
    last_char = txt[-1]
    if not last_char.isdigit():
        return False
    # Check if last_char is a standalone digit
    # Split the string by spaces and check if the last character is in a single-digit group
    parts = txt.split()
    if not parts:
        return False
    return len(parts[-1]) == 1 and parts[-1][-1] == last_char

def is_last_char_a_punctuation(txt):
    if not txt:
        return False
    last_char = txt[-1]
    return last_char in '.,!?' and not (txt[-2] == ' ' if len(txt) > 1 else False)

def round_away_from_zero(value):
    num = float(value)
    rounded = round(num)
    if abs(num - rounded) == 0.5:
        if num > 0:
            return int(num + 0.5)
        else:
            return int(num - 0.5)
    return int(rounded)
